import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/xid11')
from h import *
L=[]
L.append(T(1002829,"Roti Lemon Blueberry","Cobalah Roti Lemon Blueberry saat Anda ingin memanggang sesuatu yang manis dan ramah ginjal dengan sedikit kesegaran.","10","1 iris",
["Tepung untuk melapisi loyang roti","1-1/2 cangkir tepung terigu serbaguna","1 sendok teh baking powder","1 sendok teh soda kue","1/3 cangkir minyak kanola","1 cangkir gula","2 sendok makan ekstrak lemon, 4 putih telur besar","1/2 cangkir susu skim","1 cangkir blueberry","2 sendok makan parutan kulit lemon","1/2 cangkir air perasan lemon"],
["Panaskan oven terlebih dahulu hingga 350° F. Semprot loyang roti ukuran 9” x 5” x 3” dengan semprotan masak dan taburi dengan tepung.","Dalam mangkuk besar, campurkan tepung dan baking powder.","Dalam mangkuk lain, campurkan minyak, 2/3 cangkir gula, ekstrak, dan putih telur.","Tambahkan campuran minyak ke campuran tepung, bergantian dengan susu. Kocok hanya sampai tercampur; jangan dikocok berlebihan.","Aduk perlahan blueberry dan kulit lemon.","Tuang adonan ke dalam loyang roti dan panggang selama 40-50 menit atau sampai tusuk gigi yang ditusukkan keluar bersih.","Siapkan glasir selagi roti dipanggang. Dalam panci kecil, campurkan gula dan air perasan lemon. Panaskan hingga gula larut.","Setelah roti dikeluarkan dari oven, tusuk-tusuk bagian atasnya dengan jarak 1” lalu tuangkan glasir lemon di atas roti."],
["Penderita diabetes dapat melakukan satu atau lebih perubahan berikut:","Hilangkan glasir lemon dan kurangi porsi menjadi 1/2 iris.","Ganti gula dengan pengganti gula Splenda®. Kandungan gizi berubah menjadi 154 kalori dan 17 gram karbohidrat per iris; zat gizi lainnya tetap sama.","Dihitung sebagai 1/2 pati, 1/2 buah, kalium rendah, 1 lemak, dan 1 pilihan karbohidrat."],
["1 pati","1 buah, kalium rendah","1 lemak","1/2 kalori tinggi"]))
L.append(T(1002846,"Pasta Mediterania","Pasta Mediterania adalah hidangan pasta sederhana yang ramah ginjal untuk dua orang. Siramkan vinaigrette buatan sendiri di atas pasta dan tambahkan sedikit tomat dan keju.","2","150 gram",
["50 gram (1/3 cangkir) tomat ceri","30 gram keju rendah lemak","1 sendok makan ketumbar segar (cilantro)","1 cangkir daun bawang","100 gram pasta, matang","3 sendok makan cuka putih","2 sendok makan minyak zaitun","1-1/2 sendok makan air","lada secukupnya"],
["Kupas tomat ceri dan potong menjadi irisan.","Parut keju.","Cincang halus bawang dan ketumbar.","Campurkan pasta matang yang sudah dingin dengan tomat, keju, bawang, dan ketumbar.","Campurkan cuka, minyak zaitun, air, dan lada lalu siramkan di atas pasta.","Panaskan dengan api kecil selama 3 menit dan sajikan hangat."],
["Gunakan pasta gandum utuh untuk serat lebih banyak."],
["1/2 daging","2 pati","2 lemak"]))
L.append(T(1002857,"Crisp Persik dan Blueberry","Crisp Persik dan Blueberry ramah ginjal dan kaya antioksidan, dengan persik hangat yang empuk dan lezat di bawah taburan remah manis.","10","1/10 resep",
["7 persik segar atau 4 cangkir irisan persik kalengan, ditiriskan","1/2 cangkir blueberry, segar atau beku","semprotan masak","1/4 cangkir gula putih","1 sendok makan air perasan lemon","3/4 cangkir tepung terigu serbaguna","3/4 cangkir gula merah","1/2 cangkir margarin"],
["Buang biji dan potong persik menjadi irisan 3/4″.","Semprot loyang ukuran 12″ x 12″ dengan semprotan masak. Letakkan persik dan blueberry di dalam loyang.","Taburkan gula dan air perasan lemon di atas buah.","Dalam mangkuk, campurkan tepung dan gula merah. Gunakan dua pisau untuk memotong mentega ke dalam campuran tepung dan gula hingga menjadi remah. Taburkan","remah di atas buah.","Panggang pada suhu 375° F selama 45 menit atau lebih lama, sampai buah empuk dan remah berwarna cokelat keemasan.","Sajikan hangat atau pada suhu ruang."],
["Gunakan 4 cangkir irisan persik kalengan yang ditiriskan jika persik segar sedang tidak musimnya."],
["1 buah, kalium sedang","1 pati","2 lemak"]))
L.append(T(1002863,"Makaroni Panggang Ayam","Makaroni Panggang Ayam adalah hidangan satu wadah yang mudah dibuat dan ramah ginjal.","10","150 gram atau 1 potong sedang",
["1/2 pon makaroni","2 sendok teh minyak","1 dada ayam, sekitar 1-1/2 pon","2 siung bawang putih","1 bawang merah ukuran sedang","Jintan secukupnya","1 bawang bombai putih","3 sendok makan margarin bunga matahari (atau mentega tawar)","5 telur","1 cangkir susu 1%","1 sendok makan tepung terigu"],
["Masak makaroni dalam tiga cangkir air panas dengan satu sendok teh minyak selama 20 menit. Setelah matang, tiriskan, bilas dengan air suhu ruang dan sisihkan.","Masak dada ayam dalam satu cangkir air bersama dua siung bawang putih yang dicincang, bawang merah yang dipotong besar-besar, dan jintan. Setelah ayam matang, biarkan dingin lalu suwir-suwir.","Potong dadu halus bawang bombai putih (brunoise) dan tumis dalam wajan dengan 3 sendok makan margarin dan satu sendok teh minyak bunga matahari. Kemudian masukkan ke dalam makaroni bersama ayam.","Kocok telur dengan satu cangkir susu dan tambahkan ke dalam campuran. Aduk bahan-bahan dengan sangat rata dan tuang ke dalam loyang yang telah diolesi lemak dan ditaburi tepung agar tidak lengket.","Panggang dalam oven yang telah dipanaskan terlebih dahulu pada 180° C selama 25 menit atau hingga keemasan."],
["Kalkun dapat digunakan sebagai pengganti ayam dalam resep ini."],
["2 daging","1 pati"]))
L.append(T(1002878,"Salad Sayuran Campur","Salad Sayuran Campur terdiri dari selada yang dipadukan dengan kembang kol, mentimun, lobak, dan bawang bombai, lalu dibumbui dengan sedikit cuka. Cobalah sebagai salad yang menyegarkan untuk makan siang atau makan malam.","2","100 gram atau 1 piring kecil",
["1/2 cangkir kembang kol","1-1/2 cangkir selada","1/2 cangkir mentimun","2 lobak","1/2 bawang bombai putih kecil","1 sendok teh cuka"],
["Cuci semua sayuran.","Masukkan air ke dalam panci, didihkan, dan rebus kembang kol.","Potong selada menjadi irisan memanjang.","Iris mentimun.","Iris tipis lobak. Iris bawang bombai.","Campurkan semua sayuran dan tambahkan cuka sesuai selera."],
["Untuk meningkatkan rasa, Anda dapat menambahkan air perasan lemon atau cuka buah."],
["1-1/2 sayuran, kalium sedang"]))
L.append(T(1002887,"Saus Mojo","Cabai jalapeño, air perasan jeruk, ketumbar, jintan, dan oregano berpadu dengan minyak zaitun untuk membuat saus Mojo Kuba yang populer ini. Cobalah dengan telur atau hidangan daging.","12","2 sendok makan",
["1 cabai jalapeño","1/2 cangkir minyak zaitun","1/2 cangkir air perasan jeruk nipis","1/3 cangkir air perasan jeruk","8 siung bawang putih","1 sendok teh oregano kering","1/4 sendok teh jintan","1/2 cangkir ketumbar segar (cilantro)"],
["Buang biji cabai jalapeño.","Masukkan bahan-bahan ke dalam blender atau food processor dan haluskan hingga lembut.","Simpan saus dalam wadah tertutup di lemari es hingga satu minggu."],
["Gunakan peterseli sebagai pengganti ketumbar jika Anda mau. Ganti jalapeño dengan cabai pilihan Anda.","Sesuaikan jintan dan oregano sesuai selera.","Gunakan Saus Mojo sebagai marinade atau saus. Cobalah dengan resep Nasi ala Kuba dari Sylvia."],
["2 lemak"]))
L.append(T(1002903,"Salad Kentang dan Telur dengan Saus Kari","Salad telur rendah natrium ini memiliki perpaduan cita rasa yang unik. Cobalah pada hidangan Anda berikutnya.","6","1 telur dengan 1/2 kentang (150 gram)",
["6 telur","3 kentang ukuran sedang","1 bawang bombai ukuran sedang","1 daun bawang","2 siung bawang putih","3 sendok makan minyak sayur","1/8 sendok teh garam","lada secukupnya","200 mL (3/4 cangkir) susu skim","1 sendok makan bubuk kari","1 sendok makan tepung maizena"],
["Rebus telur selama 10 menit.","Kupas kentang dan rebus.","Setelah keduanya matang, angkat dan biarkan dingin.","Kupas telur dan potong kentang menjadi dua.","Cincang bawang bombai, daun bawang, dan bawang putih. Tumis hingga kecokelatan dalam wajan dengan minyak dan bumbui dengan garam dan lada secukupnya.","Angkat dari api segera setelah keemasan dan masukkan ke dalam food processor bersama susu dan bubuk kari. Proses hingga halus.","Masukkan saus kari ke dalam panci kecil dan larutkan tepung maizena di dalamnya.","Panaskan dan masak sambil terus diaduk dengan sendok kayu hingga mengental, lalu angkat dari api.","Potong telur menjadi dua, gabungkan dengan kentang dan siram dengan saus kari.","Hias dengan rempah segar yang dicincang halus. Sajikan segera."],
["Jika diinginkan, letakkan terlebih dahulu 2 potong telur dan setengah kentang di setiap piring, lalu siram masing-masing dengan saus kari.","Untuk mengurangi kalium, potong kentang terlebih dahulu lalu rendam dalam 2 cangkir air selama 2 – 4 jam. Kemudian letakkan di atas lap dapur bersih untuk menghilangkan kelebihan air sebelum dimasak."],
["1 daging","1 pati","1 sayuran, kalium sedang"]))
L.append(T(1002909,"Nasi Primavera","Nasi Primavera adalah hidangan pendamping yang mudah untuk melengkapi hidangan apa pun.","2","1-1/2 cangkir",
["1/2 paprika merah","1 bawang bombai ukuran sedang","3 sendok makan minyak sayur","150 gram beras","300 mL air","4 sendok makan kacang polong hijau"],
["Potong paprika menjadi potongan korek api (julienne).","Cincang halus bawang bombai.","Tumis bawang bombai dan paprika dengan sedikit minyak sampai bawang bombai lunak.","Tambahkan beras, biarkan hingga tampak bening, lalu tambahkan air dan kacang polong.","Tutup dan masak sampai nasi empuk."],
["Simpan sisa makanan di lemari es untuk hidangan cepat nanti."],
["1 sayuran, kalium sedang","2-1/2 pati","2 lemak"]))
L.append(T(1002914,"Nasi dengan Labu","Nasi dengan Labu adalah hidangan nasi istimewa yang dibuat dengan labu, bawang merah, dan bawang putih untuk tambahan rasa dan zat gizi.","5","3/4 cangkir kecil",
["1 cangkir labu (ahuyama)","1 bawang merah ukuran sedang","1 siung bawang putih","4 sendok makan minyak bunga matahari","1 cangkir beras mentah","2 cangkir air"],
["Kupas labu, cuci, dan potong dadu kecil atau parut dengan sisi parutan yang kasar.","Cincang bawang merah dan bawang putih.","Panaskan minyak dalam wajan atau panci sedang dan tumis sayuran.","Bilas beras.","Masukkan beras ke dalam sayuran, tumis selama beberapa menit dan tambahkan air.","Didihkan sampai air terserap.","Aduk nasi, tutup, dan kecilkan api agar matang perlahan hingga empuk, sekitar 15 menit.","Diamkan dan sajikan."],
["Gunakan beras merah untuk serat dan rasa yang lebih banyak."],
["1 sayuran, kalium sedang","2 pati","2 lemak"]))
L.append(T(1002918,"Ayam dengan Terong","Tambahkan cita rasa pada diet ginjal Anda dengan kari ayam dan apel lezat buatan Monica. Monica, ahli gizi ginjal DaVita dari Minnesota, membuat hidangan kari ramah ginjal dengan mengganti susu sapi dengan susu beras dan menggunakan kaldu ayam rendah natrium.","2","125 - 150 gram",
["150 gram dada ayam","60 gram terong","60 gram zukini","30 gram bawang bombai","20 gram paprika merah","60 siung bawang putih","3 siung bawang putih","1 cc (1 sendok teh) minyak","1 sejumput lada"],
["Bilas ayam, buang kulitnya, dan masak sekitar 20 menit.","Cuci terong dan zukini lalu, tanpa dikupas, potong menjadi potongan selebar sekitar 1 sentimeter. Sisihkan.","Kupas bawang bombai dan potong kotak-kotak sedikit lebih kecil dari terong; sisihkan juga.","Cuci paprika, belah dua, buang bijinya, dan potong kotak-kotak kecil. Sisihkan.","Celupkan tomat matang ke dalam air mendidih selama beberapa detik, kupas, dan cincang halus. Sisihkan.","Kupas dan memarkan siung bawang putih lalu sisihkan.","Panaskan 1 sendok makan minyak dalam panci. Masukkan bawang bombai cincang. Biarkan layu tanpa terlalu kecokelatan, sambil diaduk sesekali.","Masukkan terong ke dalam panci dan tumis sekitar 2 menit dengan api sedang.","Tambahkan paprika dan biarkan sedikit layu. Aduk sesekali dengan sendok kayu.","Tambahkan ayam yang sudah dimasak sebelumnya.","Tambahkan zukini dan bawang putih yang dimemarkan lalu masak 1 atau 2 menit dengan api kecil, kemudian segera tambahkan tomat cincang dan aduk lagi. Tambahkan lada dan biarkan semuanya matang dengan api kecil selama sekitar 15 menit atau sampai sayuran matang."],
["Jangan masukkan terong dan zukini terlalu cepat, atau tekstur dan rasanya akan hilang.","Untuk mengurangi kalium dalam resep ini, Anda dapat memotong dadu terong dan zukini, lalu merendamnya dalam air hangat selama 2 hingga 4 jam. Buang airnya dan lanjutkan resep."],
["2-1/2 daging","1-1/2 sayuran, kalium sedang"]))
L.append(T(1002939,"Burger Daging Sapi dan Lentil","Lentil, putih telur, dan daging sapi giling adalah tiga sumber protein dalam Burger Daging Sapi dan Lentil ini. Lentil menambah serat sebanyak 2.6 gram.","5","sekitar 100 gram",
["100 gram lentil (mentah)","1 sendok makan bawang putih","1/4 cangkir bawang bombai","1/4 cangkir paprika","3 putih telur","100 gram daging sapi giling","2 sendok makan tepung terigu","50 mL minyak bunga matahari"],
["Rendam lentil dalam air selama 6 jam sebelum membuat burger, dan ganti air setiap 2 jam.","Memarkan bawang putih dan cincang bawang bombai dan paprika.","Giling atau haluskan lentil menjadi adonan, sambil menambahkan bawang putih, bawang bombai, dan paprika.","Uleni hingga rata, tambahkan ketiga putih telur, daging sapi giling, dan 2 sendok makan tepung terigu lalu lanjutkan menguleni.","Panaskan minyak dalam wajan sambil membentuk burger dengan tangan.","Goreng burger di kedua sisi hingga cokelat keemasan, dan perhatikan agar tidak gosong."],
["Sebagai pengganti tepung, Anda dapat menambahkan remah roti, dan Anda dapat menambahkan ketumbar segar atau peterseli (15 gram) sesuai selera.","Anda juga dapat menggunakan kacang-kacangan lain, seperti kacang polong hijau atau buncis, sesuai keinginan Anda. Anda dapat membuat bola-bola daging dari adonan yang sama.","Anda juga dapat menggunakan kacang-kacangan lain, seperti kacang polong hijau atau buncis, sesuai keinginan Anda."],
["2 daging","1/2 lemak","1 pati","1 sayuran, kalium rendah"]))
L.append(T(1002949,"Nasi ala Kuba","Nasi berbumbu ketumbar, jintan, dan oregano, ditambah pisang plantain keemasan yang disajikan dengan telur, adalah bahan-bahan dalam versi Nasi ala Kuba yang lezat dan lebih rendah kalium ini.","4","2/3 cangkir campuran nasi, 3 potong plantain, 2 telur",
["1 cangkir beras putih butir panjang mentah","1 lembar daun salam","1 bawang bombai putih kecil","1 tomat Roma ukuran sedang","1 pisang plantain ukuran sedang","1 sendok teh ketumbar segar (cilantro)","2 siung bawang putih","1 jeruk nipis","1/2 sendok teh oregano kering","1/4 sendok teh jintan, atau secukupnya","1/2 sendok teh garam","2 sendok makan minyak zaitun","8 telur besar"],
["Siapkan nasi dalam penanak nasi atau sesuai petunjuk kemasan. Tambahkan daun salam dan air sebelum dimasak. Cincang bawang bombai dan tomat. Kupas lalu potong","plantain secara diagonal menjadi 12 potong. Cincang ketumbar dan bawang putih. Potong jeruk nipis menjadi empat bagian.","Campurkan oregano kering, jintan, dan garam dalam mangkuk yang sangat kecil. Sisihkan.","Dalam wajan 2 kuart dengan api sedang, tumis bawang bombai dan bawang putih dalam 1/2 sendok makan minyak zaitun. Setelah bawang putih dan bawang bombai harum, tambahkan tomat dan masak selama beberapa menit.","Tambahkan nasi yang sudah dikukus dan ketumbar lalu aduk. Taburkan bumbu kering di atasnya dan aduk hingga semua bahan tercampur; sisihkan.","Dalam wajan, panaskan 1/2 sendok makan minyak zaitun, masukkan plantain dan masak selama 2 menit, balik dan masak hingga cokelat keemasan.","Dalam wajan terpisah, panaskan 1 sendok makan minyak zaitun dengan api sedang, pecahkan telur ke dalam wajan dan masak sesuai tingkat kematangan yang diinginkan.","Di atas piring, letakkan 1/2 cangkir nasi dan 3 potong plantain. Letakkan 2 telur di atas setiap porsi.","Peras air jeruk nipis dari satu potongan di atas setiap piring."],
["Porsi plantain sedikit karena plantain tinggi kalium. Jika Anda tidak menjalani diet rendah kalium, plantain dapat ditambah menjadi 2 buah sedang atau 1 buah besar.","Saat memasak nasi, gunakan perbandingan 1:2: 1 cangkir beras untuk 2 cangkir air.","Jika Anda tidak memiliki lemon atau jeruk nipis, cobalah percikkan 1/4 sendok teh cuka pada setiap porsi untuk menambah rasa."],
["2 daging","2 pati","1/2 buah, kalium tinggi","1 lemak"]))
L.append(T(1002955,"Sup Andes","Buatlah resep sup Andes yang ramah ginjal ini, dan seluruh keluarga Anda pasti akan meminta tambah!","4","3/4 cangkir atau 200 mL",
["1 bawang bombai putih ukuran sedang","1 batang daun bawang","3 siung bawang putih","1/4 pon keju mozzarella rendah lemak","4 kentang ukuran sedang","1/2 liter kaldu ayam rendah natrium","1/2 liter air","2 ons susu","1 tangkai ketumbar segar (cilantro)","4 telur"],
["Cincang halus bawang dan ketumbar. Memarkan bawang putih.","Potong keju menjadi potongan kecil.","Kupas kentang dan potong dadu. Tutupi kentang seluruhnya dengan air dan didihkan. Tiriskan dan ulangi prosesnya. Sisihkan kentang.","Didihkan kaldu bersama bawang dan bawang putih.","Masukkan kentang, susu, dan keju sambil diaduk.","Setelah keju meleleh, tambahkan ketumbar.","Setelah api dimatikan, masukkan 4 telur ke dalam sup satu per satu, dan berhati-hatilah agar kuning telurnya tidak pecah."],
["Carilah kaldu ayam rendah kalium yang tidak mengandung kalium klorida.","Tidak dianjurkan jika fosfor belum terkendali."],
["1 daging","1 pati","1 sayuran, kalium sedang","1 susu dan olahannya"]))
L.append(T(1002963,"Pincho Ayam","Sate ayam panggang berbumbu adobo dan saus barbekyu jambu biji pasti akan menyenangkan semua orang di meja makan.","8","1 tusuk",
["2 pon paha ayam tanpa tulang dan tanpa kulit","2 sendok makan bumbu adobo","1 sendok makan oregano kering","1 sendok makan cuka putih","2 sendok makan minyak zaitun","2 lembar daun salam","1 cangkir saus BBQ jambu biji (lihat resep di DaVita.com)","8 tusuk sate logam atau bambu"],
["Potong paha ayam menjadi potongan seukuran suapan dua inci. Jika menggunakan tusuk bambu, rendam dalam air selama 1/2 jam agar tidak terbakar.","Campurkan bumbu adobo, oregano, cuka, minyak zaitun, dan daun salam lalu masukkan ke dalam kantong ber-zip.","Masukkan ayam ke dalam marinade. Dinginkan di lemari es setidaknya setengah jam atau semalaman.","Panaskan panggangan dan olesi jeruji dengan minyak setelah panas.","Tusukkan ayam pada tusuk sate dan letakkan di atas panggangan panas. Panggang hingga kecokelatan selama 5 menit di setiap sisi.","Olesi sate dengan saus barbekyu jambu biji atau saus barbekyu rendah natrium lainnya dan masak sekitar 4 menit lagi."],
["Jaga agar potongan ayam berukuran sama agar matang merata.","Temukan resep saus barbekyu jambu biji dan saus barbekyu rendah natrium lainnya di DaVita.com."],
["3 daging"]))
L.append(T(1002965,"Buncis Deviled","Tambahkan sentuhan cita rasa pada hidangan Anda berikutnya dengan resep Buncis Deviled yang ramah ginjal ini. Mustard kuning, lada hitam, dan saus Worcestershire mengubah buncis biasa menjadi sajian deviled yang lezat.","4","1/2 cangkir",
["2 cangkir buncis beku","5 sendok teh margarin tawar, dibagi","2 sendok teh mustard","1/2 sendok teh lada hitam","1 sendok teh saus Worcestershire","1 sendok makan remah roti berbumbu kering"],
["Siapkan buncis sesuai petunjuk kemasan.","Buat saus dengan mencampur 2 sendok teh margarin cair, mustard, lada, dan saus Worcestershire. Panaskan campuran dalam microwave selama 30 detik.","Aduk saus dengan buncis panas.","Campurkan sisa margarin (cair) dengan remah roti. Taburkan di atas buncis dan sajikan."],
["Buncis segar atau kalengan rendah natrium dapat digunakan sebagai pengganti buncis beku."],
["1 sayuran, kalium sedang","1 lemak"]))
save(2,L)
